const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=o=>JSON.parse(JSON.stringify(o)),uid=()=>globalThis.crypto?.randomUUID?.()||'r'+Date.now().toString(36)+Math.random().toString(36).slice(2);
const nf=(n,d=2)=>Number(n).toLocaleString('sv-SE',{maximumFractionDigits:d,minimumFractionDigits:d}),number=v=>Number(String(v).replace(/\s/g,'').replace(',','.'));
const palette=['#146cd4','#df573a','#098475','#a24abd','#be8105','#335775'];
