let S={format:'ritningsrummet',version:8,sections:[],sectionSlots:[null,null],name:'Ny granskning',documents:[],pages:[],layers:[layer('Granskning',palette[0])],activePage:null,activeLayer:null};S.activeLayer=S.layers[0].id;
let tool='select',draft=[],hover=null,snapPoint=null,selected=null,drag=null,space=false,dirty=false,importing=false,calibrationMode='uniform',selectedLayerEditor=false;
let style={stroke:2.5,font:18,fontFamily:'segoe',fontBold:false,fontItalic:false,fontUnderline:false,color:null},vehicleSettings={gear:1,vehicle:clone(VEHICLES[0]),radius:9,margin:.25},view={x:0,y:0,z:1},cw=0,ch=0,raf=0,history=[],future=[],animation=null;
const renderCache=new Map(),pdfCache=new Map(),sweepCache=new Map();
const page=()=>S.pages.find(p=>p.id===S.activePage),activeLayer=()=>S.layers.find(l=>l.id===S.activeLayer),findObj=()=>page()?.objects.find(o=>o.id===selected),getLayer=id=>S.layers.find(l=>l.id===id);
const scaled=p=>p?.scale?.x>0&&p?.scale?.y>0,confirmed=p=>scaled(p)&&['confirmed','calibrated','checked'].includes(p.scale.status);
const unit=p=>Math.max(p?.w||1200,p?.h||800)/1200;
function pageAppearance(p=page()){return p?.appearance||{line:1,text:1};}
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5500);}
function busy(msg){$('busyText').textContent=msg;$('busy').hidden=false;}function unbusy(){$('busy').hidden=true;}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function closeModal(){$('modal').close();}
function errorBox(e){unbusy();console.error(e);modal('Det gick inte att slutföra',`<p class="note error">${esc(e.message||e)}</p><div class="modal-actions"><button id="errorOK">Stäng</button></div>`);$('errorOK').onclick=closeModal;}
function changed(){dirty=true;$('saveState').textContent='Ändringar som inte sparats';requestRender();}
function editState(){return JSON.stringify({pages:S.pages.map(p=>({id:p.id,objects:p.objects,scale:p.scale,baseOpacity:p.baseOpacity,w:p.w,h:p.h,name:p.name,paper:p.paper,appearance:pageAppearance(p)})),layers:S.layers,activeLayer:S.activeLayer,sections:S.sections||[],sectionSlots:S.sectionSlots||[null,null]});}
function snapshot(){history.push(editState());if(history.length>50)history.shift();future=[];}
function restoreHistory(from,to){if(!from.length)return;to.push(editState());const saved=JSON.parse(from.pop());for(const p of saved.pages){const actual=S.pages.find(q=>q.id===p.id);if(actual)Object.assign(actual,p);}S.layers=saved.layers;S.activeLayer=saved.activeLayer;S.sections=saved.sections||[];S.sectionSlots=saved.sectionSlots||[null,null];selected=null;draft=[];sweepCache.clear();changed();renderUI();}
function setTool(t){if(importing)return;if(['pen','line','rect','area','text','measure','vehicle','street','lark','pilbil'].includes(t)&&!page()){toast('Öppna en ritning eller skapa ett blankt papper först.');return;}if(['vehicle','pilbil'].includes(t)&&!confirmed(page())){toast('Bekräfta eller kalibrera skalan innan du testar körspår.');openScale();return;}if(t==='lark'&&!confirmed(page())){toast('Bekräfta skalan först, eller skapa ett blankt papper med vald skala.');openScale();return;}if(t==='street'){if(!confirmed(page())){toast('Bekräfta eller kalibrera skalan innan du placerar sektionen.');openScale();return;}if(!getSection(streetSectionId))streetSectionId=S.sections?.find(s=>s.items.length&&s.name.trim())?.id;if(!getSection(streetSectionId)){switchWorkspace('sections');toast('Bygg och döp en sektion först.');return;}}draft=[];drag=null;selected=null;selectedLayerEditor=false;tool=t;document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===t);b.setAttribute('aria-pressed',b.dataset.tool===t);});renderInspector();renderStatus();requestRender();if(innerWidth<930&&['vehicle','text','pen','street'].includes(t))showRightPanel();}
const icons={pilbil:'M12 3a9 9 0 100 18 9 9 0 000-18M3 11l7 1m4 0 7-1M12 14v7M12 10a2 2 0 100 4 2 2 0 000-4',street:'M3 4v16M8 4v16M16 4v16M21 4v16M11 7h2m-2 5h2m-2 5h2',select:'M5 3l13 10-6 1-3 6z',hand:'M6 11V6a1.5 1.5 0 013 0v5-7a1.5 1.5 0 013 0v7-6a1.5 1.5 0 013 0v6-3a1.5 1.5 0 013 0v7c0 4-3 6-6 6-2 0-4-1-6-4l-3-4a1.5 1.5 0 012-2l2 2',pen:'M4 20l1-5L16 4a2 2 0 013 3L8 18zM13 7l4 4',line:'M4 19L20 4M4 16v3h3M17 4h3v3',rect:'M4 5h16v14H4z',text:'M4 5V3h16v2M12 3v18M8 21h8',measure:'M3 17L17 3l4 4L7 21zM8 12l3 3M12 8l3 3M16 4l3 3',area:'M4 17l3-12 13 4-3 11zM7 5l10 15M4 17L20 9',vehicle:'M4 17v-6l2-6h12l2 6v6M4 12h16M7 15h1m8 0h1M6 17v3m12-3v3M5 9h14',erase:'M3 14l10-11 8 8-9 10H9zM7 10l8 8M12 21h9',calibrate:'M3 5h18M3 3v4m18-4v4M4 15h16M12 9v12M8 12l4-3 4 3'};
const toolNames={pilbil:'Pilbil',landscape:'LARK-element',lark:'LARK',street:'Gatusektion',select:'Välj',hand:'Flytta vy',pen:'Frihand',line:'Linje',rect:'Rektangel',text:'Text',measure:'Längd',area:'Area',vehicle:'Körspår',erase:'Radera',calibrate:'Kalibrera'};
const hints={pilbil:'Placera bakaxeln och ange nosriktningen. Piltangenter: ratt vänster/höger, framåt/backa. Enter avslutar.',lark:'Välj ett LARK-element. Klicka för symboler; rita konturen och tryck Enter för ytor.',street:'Klicka längs sektionens mittlinje. Enter avslutar. Bredden hämtas från den namngivna sektionen.',select:'Klicka för att markera. Dra objekt eller handtag. Dubbelklicka på text för att redigera.',hand:'Dra för att flytta vyn. Rulla för att zooma.',pen:'Håll ned och rita. Mellanslag + dra flyttar vyn.',line:'Klicka på start- och slutpunkt. Shift låser riktningen till 45°.',rect:'Klicka på två motsatta hörn.',text:'Klicka där texten ska placeras.',measure:'Klicka längs sträckan. Avsluta med Enter eller dubbelklick.',area:'Klicka runt ytan. Avsluta med Enter eller klick på första punkten.',vehicle:'Placera bakaxeln och ange nosriktning. Välj Framåt / Backa och klicka mål. Högerklick växlar riktning. Enter avslutar.',erase:'Klicka på ett objekt för att radera det. Ctrl+Z ångrar.',calibrate:'Klicka på referensmåttets två ändpunkter. Zooma in för bättre precision.'};
function initTools(){$('tools').innerHTML=['select','hand','pen','line','rect','text','measure','area','vehicle','pilbil','street','erase'].map((t,i)=>`<button class="tool ${i===2||i===6||i===8?'sep':''} ${t===tool?'active':''}" data-tool="${t}" title="${toolNames[t]}" aria-pressed="${t===tool}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[t]}"/></svg><span>${toolNames[t]}</span></button>`).join('');document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));}
function renderStatus(){const p=page();$('toolHint').textContent=p?hints[tool]:'Öppna en ritning eller skapa ett blankt papper.';$('pageState').textContent=p?`${p.name}`:'Ingen ritning';$('drawing').style.cursor=space||tool==='hand'?'grab':tool==='select'?'default':'crosshair';$('draftActions').hidden=!(draft.length&&['measure','area','vehicle','street','lark'].includes(tool));$('draftLabel').textContent=tool==='vehicle'?(draft.length===1?'Ange nosriktning':`${vehicleSettings.gear===-1?'BACKA':'FRAMÅT'} · ${Math.max(0,draft.length-2)} delsträckor`):`${draft.length} punkter`;$('undo').disabled=!history.length;$('redo').disabled=!future.length;if(typeof renderPilbil==='function')renderPilbil();}
function renderDocuments(){$('documents').innerHTML=S.pages.length?S.pages.map(p=>`<div class="doc-row"><button class="doc-button ${p.id===S.activePage?'active':''}" data-page="${p.id}"><span class="doc-icon">${esc(p.kind==='blank'?'ARK':p.kind.toUpperCase())}</span><span class="doc-name">${esc(p.name)}<span class="doc-meta">${p.objects.length} objekt · ${scaled(p)?(confirmed(p)?'skala angiven':'skalförslag'):'skala saknas'}</span></span></button></div>`).join(''):'<p class="muted">Läs in din första ritning.</p>';document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>activatePage(b.dataset.page));const p=page();$('fileInfo').textContent=p?(['pdf','blank'].includes(p.kind)?`${nf(p.w*25.4/72,0)} × ${nf(p.h*25.4/72,0)} mm · ${p.kind==='blank'?'Blankt papper':'PDF-sida '+p.number}`:p.kind==='dxf'?`${p.cad?.shapes.length.toLocaleString('sv-SE')} CAD-objekt · modellrymd`:`${p.w} × ${p.h} bildpunkter`):'';$('baseOpacityWrap').style.display=p?'flex':'none';if(p)$('baseOpacity').value=Math.round((p.baseOpacity??1)*100);}
function renderLayers(){$('layers').innerHTML=S.layers.slice().reverse().map(l=>`<div class="layer ${l.id===S.activeLayer?'active':''} ${!l.visible?'invisible':''}"><button class="layer-mini" data-vis="${l.id}" title="${l.visible?'Dölj':'Visa'} lager" aria-label="${l.visible?'Dölj':'Visa'} ${esc(l.name)}">${l.visible?'◉':'○'}</button><span class="layer-swatch" style="background:${esc(l.color)}"></span><button class="layer-name" data-layer="${l.id}" title="${esc(l.name)}">${esc(l.name)}</button><button class="layer-mini" data-lock="${l.id}" title="${l.locked?'Lås upp':'Lås'}">${l.locked?'▣':'◇'}</button><button class="layer-mini" data-edit-layer="${l.id}" title="Redigera lager">⋯</button></div>`).join('');document.querySelectorAll('[data-vis]').forEach(b=>b.onclick=()=>{snapshot();const l=getLayer(b.dataset.vis);l.visible=!l.visible;if(selected&&findObj()?.layerId===l.id)selected=null;changed();renderUI();});document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>{snapshot();getLayer(b.dataset.lock).locked=!getLayer(b.dataset.lock).locked;changed();renderUI();});document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{S.activeLayer=b.dataset.layer;selected=null;selectedLayerEditor=false;renderLayers();renderInspector();});document.querySelectorAll('[data-edit-layer]').forEach(b=>b.onclick=()=>{S.activeLayer=b.dataset.editLayer;selected=null;selectedLayerEditor=true;renderLayers();renderInspector();showRightPanel();});}
function scaleDescription(p){if(!scaled(p))return 'Skala saknas';const s=p.scale,base=s.ratio?`1:${nf(s.ratio,0)}`:`${nf(s.x,5)} m/enhet`;return`${base} · ${s.method||''}`;}
function renderScale(){const p=page(),s=p?.scale;$('scaleBtn').disabled=!p;$('calibrateBtn').disabled=!p;const status=!scaled(p)?'Saknas':s.status==='proposed'?'Förslag':s.status==='checked'?'Kontrollerad':s.status==='calibrated'?'Kalibrerad':'Bekräftad';$('scaleStatus').textContent=status;$('scaleStatus').className='pill '+(confirmed(p)?'ok':'warn');$('scaleValue').textContent=!p?'Ingen ritning vald':!scaled(p)?'Referensmått behövs':s.ratio?`1:${nf(s.ratio,0)}`:s.method==='CAD-enhet'?`CAD i ${p.cad?.unit?.name||'angiven enhet'}`:'Skala från referensmått';$('scaleDetail').textContent=!p?'Läs in ett underlag för att börja.':!scaled(p)?'Ingen säker skala kunde bestämmas. Kalibrera innan du mäter.':s.status==='proposed'?'Förslaget behöver kontrolleras. Mått visas som preliminära.':`${s.method}. ${s.check?`Kontrollavvikelse ${nf(s.check.error*100,1)} %.`:'Kontrollmät gärna ett andra känt avstånd.'}`;$('canvasBanner').hidden=!p||confirmed(p)||draft.length>0;$('canvasBanner').textContent=scaled(p)?'Skalförslag — kontrollera innan måtten används.':'Skala saknas — mått visas i ritningsenheter.';}
function measureLabel(o,p=page()){if(LC.isSurface(o))o={...o,kind:'area'};if(o.kind==='area'&&!RR.simplePolygon(o.points))return 'Korsande kanter';const s=scaled(p)?p.scale:{x:1,y:1},val=o.kind==='area'?RR.area(o.points,s):RR.length(o.points,s,o.kind==='area'),u=scaled(p)?(o.kind==='area'?'m²':'m'):(o.kind==='area'?'enheter²':'enheter');return`${scaled(p)&&!confirmed(p)?'≈ ':''}${nf(val,scaled(p)?2:1)} ${u}`;}
function renderMeasurements(){const p=page(),os=p?.objects.filter(o=>(['measure','area'].includes(o.kind)||LC.isSurface(o))&&getLayer(o.layerId)?.visible)||[];$('measurementCount').textContent=os.length;$('measurements').innerHTML=os.length?os.map(o=>`<div class="measure-row" tabindex="0" role="button" data-measure="${o.id}"><span class="legend-line" style="background:${esc(o.color||getLayer(o.layerId)?.color)}"></span><div><strong>${measureLabel(o)}</strong><small>${esc(o.name||toolNames[o.kind])} · ${esc(getLayer(o.layerId)?.name)}</small></div></div>`).join(''):'<p class="muted">Mått på den här sidan visas här.</p>';document.querySelectorAll('[data-measure]').forEach(b=>{b.onclick=()=>selectObject(b.dataset.measure);b.onkeydown=e=>{if(e.key==='Enter')b.click();};});}
function renderUI(){if(typeof renderAppearance==='function')renderAppearance();renderDocuments();renderLayers();renderScale();renderInspector();renderMeasurements();renderStatus();if(typeof workspaceMode!=='undefined'&&workspaceMode==='sections')renderSections();if(typeof workspaceMode!=='undefined'&&workspaceMode==='lark')renderLarkPalette();requestRender();}
function field(label,id,value,type='text',attrs=''){return`<label class="field"><span>${label}</span><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function selectObject(id){tool='select';selected=id;selectedLayerEditor=false;const o=findObj();if(o)S.activeLayer=o.layerId;renderUI();document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool==='select'));showRightPanel();}
function renderInspector(){const el=$('inspector'),p=page(),o=findObj(),l=activeLayer();$('inspectorHeading').textContent=o?'Markerat objekt':selectedLayerEditor?'Lageregenskaper':'Verktyg & objekt';
 if(selectedLayerEditor&&l){el.innerHTML=field('Lagernamn','layerName',l.name)+field('Lagerfärg','layerColor',l.color,'color')+`<label class="field"><span>Genomskinlighet</span><input id="layerOpacity" type="range" min="10" max="100" value="${l.opacity*100}"></label><div class="row"><button id="layerUp" class="small">Flytta upp</button><button id="layerDown" class="small">Flytta ned</button></div><button id="deleteLayer" class="full danger">Ta bort lager</button>`;$('layerName').onchange=()=>{snapshot();l.name=$('layerName').value.trim()||'Lager';changed();renderLayers();};$('layerColor').onchange=()=>{snapshot();l.color=$('layerColor').value;changed();renderUI();};$('layerOpacity').onchange=()=>{snapshot();l.opacity=number($('layerOpacity').value)/100;changed();};$('layerUp').onclick=()=>moveLayer(1);$('layerDown').onclick=()=>moveLayer(-1);$('deleteLayer').onclick=deleteLayer;return;}
 if(o){const locked=getLayer(o.layerId)?.locked;el.innerHTML=`<div class="property-title">${esc(toolNames[o.kind]||o.kind)}</div>${locked?'<p class="note warn">Lagret är låst. Lås upp för att redigera.</p>':''}`+field('Namn / beteckning','objName',o.name||'')+`<label class="field"><span>Lager</span><select id="objLayer">${S.layers.map(x=>`<option value="${x.id}" ${x.id===o.layerId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`+field('Objektfärg','objColor',o.color||getLayer(o.layerId)?.color,'color')+`<button class="link-button small" id="inheritColor">Använd lagerfärg</button>`+(o.kind==='text'?`<label class="field"><span>Text</span><textarea id="objText" maxlength="10000">${esc(o.text)}</textarea></label>${textFormatPanel('objFormat',textFormat(o))}`:'')+(o.kind==='measure'||o.kind==='area'?`<div class="metrics"><div class="metric"><small>${o.kind==='area'?'Area':'Längd'}</small><strong>${measureLabel(o)}</strong></div>${o.kind==='area'?`<div class="metric"><small>Omkrets</small><strong>${nf(RR.length(o.points,scaled(p)?p.scale:undefined,true))} ${scaled(p)?'m':'enh.'}</strong></div>`:''}</div>`:'')+(o.kind==='vehicle'?(o.drive?.control==='pilbil'?pilbilPanel(o):vehiclePanel(o)):o.kind==='street'?streetPanel(o):o.kind==='landscape'?larkPanel(o):'')+`<div class="row" style="margin-top:15px"><button id="duplicateObj" class="small">Duplicera</button><button id="deleteObj" class="small danger">Radera</button></div><p class="tiny" style="margin-top:12px">Dra objektet för att flytta det. Dra en nod för att ändra geometrin.</p>`;
  for(const id of ['objName','objLayer','objColor','objText'])if($(id)){$(id).disabled=locked;$(id).onchange=()=>{snapshot();if(id==='objLayer'){if(getLayer($(id).value)?.locked){toast('Mållagret är låst.');renderInspector();return;}o.layerId=$(id).value;S.activeLayer=o.layerId;}else o[{objName:'name',objColor:'color',objText:'text'}[id]]=$(id).value;sweepCache.delete(o.id);changed();renderUI();};}
  $('inheritColor').onclick=()=>{if(locked)return;snapshot();delete o.color;changed();renderUI();};$('duplicateObj').disabled=locked;$('deleteObj').disabled=locked;$('duplicateObj').onclick=()=>{snapshot();const q=clone(o);q.id=uid();q.points=q.points.map(a=>({x:a.x+20/view.z,y:a.y+20/view.z}));p.objects.push(q);selected=q.id;changed();renderUI();};$('deleteObj').onclick=deleteSelected;if(o.kind==='vehicle'){if(o.drive?.control==='pilbil')bindPilbil(o);else bindVehicle(o);}if(o.kind==='street')bindStreet(o);if(o.kind==='landscape')bindLark(o);if(o.kind==='text')bindTextFormat('objFormat',textFormat(o),f=>{if(getLayer(o.layerId)?.locked)return;snapshot();Object.assign(o,textFields(f));changed();},locked,'objText');return;
 }
 if(tool==='pilbil'){el.innerHTML=pilbilPanel();bindPilbil();return;}
 if(tool==='lark'){el.innerHTML=larkPanel();bindLark();return;}
 if(tool==='street'){el.innerHTML=streetPanel();bindStreet();return;}
 if(tool==='vehicle'){el.innerHTML='<div class="property-title">Testa körspår</div>'+vehiclePanel();bindVehicle();return;}
 if(tool==='calibrate'){el.innerHTML=`<div class="property-title">Referensmått</div><p class="muted">${calibrationMode==='check'?'Mät ett annat känt avstånd för att kontrollera skalan.':'Placera två punkter på en måttlinje eller skalstock.'}</p><div class="note" style="margin-top:15px">Välj ett långt, tydligt mått. Zooma in vid varje ändpunkt. Förstoringsrutan hjälper dig att placera punkten.</div><button id="cancelCal" class="full">Avbryt</button>`;$('cancelCal').onclick=()=>setTool('select');return;}
 el.innerHTML=`<div class="property-title">${toolNames[tool]}</div><p class="muted">${hints[tool]}</p>`+(p&&['pen','line','rect','text','measure','area'].includes(tool)?`<div class="row">${field('Färg','drawColor',style.color||l?.color||palette[0],'color')}${tool==='text'?'':field('Linje','drawWidth',style.stroke,'number','min="0.5" max="20" step="0.5"')}</div>${tool==='text'?textFormatPanel('drawFormat',textFormat()):''}<p class="tiny">Lager: ${esc(l?.name)}${l?.locked?' · låst':''}</p>`:'')+(!p?'<div class="note" style="margin-top:18px">Börja med att läsa in ett underlag. Välj sedan skala, lager och verktyg.</div>':'')+`<button id="inspectHelp" class="full link-button">Snabbguide & begränsningar</button>`;
 if($('drawColor'))$('drawColor').onchange=()=>style.color=$('drawColor').value;if($('drawWidth'))$('drawWidth').onchange=()=>style.stroke=RR.clamp(number($('drawWidth').value)||2.5,.5,20);if($('drawFormatSize'))bindTextFormat('drawFormat',textFormat(),f=>{style.font=f.size;Object.assign(style,{fontFamily:f.family,fontBold:f.bold,fontItalic:f.italic,fontUnderline:f.underline});});$('inspectHelp').onclick=openHelp;
}
function moveLayer(d){const i=S.layers.findIndex(l=>l.id===S.activeLayer),j=i+d;if(j<0||j>=S.layers.length)return;snapshot();[S.layers[i],S.layers[j]]=[S.layers[j],S.layers[i]];changed();renderLayers();}
function deleteLayer(){const l=activeLayer();if(S.layers.length<2){toast('Behåll minst ett granskningslager.');return;}const n=S.pages.reduce((a,p)=>a+p.objects.filter(o=>o.layerId===l.id).length,0);modal('Ta bort lager',`<p>Ta bort ${esc(l.name)} och dess ${n} objekt på alla sidor?</p><div class="modal-actions"><button id="keepLayer">Avbryt</button><button id="confirmDeleteLayer" class="danger">Ta bort</button></div>`);$('keepLayer').onclick=closeModal;$('confirmDeleteLayer').onclick=()=>{snapshot();S.layers=S.layers.filter(x=>x.id!==l.id);S.pages.forEach(p=>p.objects=p.objects.filter(o=>o.layerId!==l.id));S.activeLayer=S.layers.at(-1).id;selected=null;selectedLayerEditor=false;closeModal();changed();renderUI();};}
function deleteSelected(){const p=page(),o=findObj();if(!o||getLayer(o.layerId)?.locked)return;snapshot();p.objects=p.objects.filter(x=>x.id!==o.id);selected=null;changed();renderUI();}
function writable(){const l=activeLayer();if(!l||l.locked||!l.visible){toast('Välj ett synligt, olåst lager först.');return false;}return true;}
function addObject(kind,points,extra={}){if(!writable())return;const p=page();snapshot();const o={id:uid(),kind,layerId:S.activeLayer,points:clone(points),width:style.stroke*unit(p),fontSize:style.font*unit(p),name:'',...extra};if(style.color)o.color=style.color;p.objects.push(o);selected=o.id;draft=[];changed();renderUI();return o;}
function worldPos(e){const r=$('drawing').getBoundingClientRect();return{x:(e.clientX-r.left-view.x)/view.z,y:(e.clientY-r.top-view.y)/view.z};}
function screen(p){return{x:p.x*view.z+view.x,y:p.y*view.z+view.y};}
function snapped(pt,e){snapPoint=null;if($('snap').checked&&!e.altKey){let near=10/view.z;const tryPoint=q=>{const d=RR.dist(pt,q);if(d<near){near=d;snapPoint=q;}};for(const o of page()?.objects||[])if(o.id!==selected&&getLayer(o.layerId)?.visible)for(const q of o.points)tryPoint(q);if(page()?.cad?.shapes)for(const o of page().cad.shapes){if(o.type==='text')continue;for(const q of o.points)tryPoint(q);}if(snapPoint)pt={...snapPoint};}if(e.shiftKey&&draft.length){const a=draft.at(-1),angle=Math.round(Math.atan2(pt.y-a.y,pt.x-a.x)/(Math.PI/4))*Math.PI/4,len=RR.dist(a,pt);pt={x:a.x+Math.cos(angle)*len,y:a.y+Math.sin(angle)*len};}return pt;}
function hitObject(pt){const p=page();if(!p)return null;for(const l of S.layers.slice().reverse()){if(!l.visible)continue;for(const o of p.objects.slice().sort((a,b)=>Number(LC.isSurface(b))-Number(LC.isSurface(a))).reverse()){if(o.layerId!==l.id)continue;let ps=o.points;if(o.kind==='landscape'&&scaled(p)&&RR.inside(pt,LC.footprint(o,p.scale)))return o.id;if(o.kind==='street'){try{if(streetGeometry(o,p).bands.some(b=>RR.inside(pt,b.polygon)))return o.id;}catch{}}if(o.kind==='vehicle'){const sw=getSweep(o,p);if(sw&&sw.frames.some(f=>RR.inside(pt,f.body)))return o.id;}if(o.kind==='text'){const b=textLayout(ctx,o,p).bounds,pad=3/view.z;if(pt.x>=b.minX-pad&&pt.x<=b.maxX+pad&&pt.y>=b.minY-pad&&pt.y<=b.maxY+pad)return o.id;}if(['area','rect'].includes(o.kind)&&RR.inside(pt,objectPoints(o)))return o.id;for(let i=1;i<ps.length;i++)if(RR.segDist(pt,ps[i-1],ps[i])<8/view.z+(o.width||1)/2)return o.id;for(const q of ps)if(RR.dist(pt,q)<8/view.z)return o.id;}}return null;}
function objectPoints(o){if(o.kind==='rect'&&o.points.length===2){const[a,b]=o.points;return[a,{x:b.x,y:a.y},b,{x:a.x,y:b.y}];}return o.points;}
function handleDown(e){if(!page()||importing||(e.button===2&&tool!=='vehicle'))return;if(e.button===2){e.preventDefault();setVehicleGear(-vehicleSettings.gear);return;}$('viewport').focus();const raw=worldPos(e);if(e.button===1||space||tool==='hand'){drag={kind:'pan',start:{x:e.clientX,y:e.clientY},view:{...view}};$('drawing').setPointerCapture(e.pointerId);return;}const pt=snapped(raw,e);if(tool==='select'){const o=findObj();if(o&&!getLayer(o.layerId)?.locked){const i=o.points.findIndex(q=>RR.dist(q,pt)<8/view.z);if(i>=0){drag={kind:'node',id:o.id,index:i};$('drawing').setPointerCapture(e.pointerId);return;}}const id=hitObject(pt);selected=id;selectedLayerEditor=false;if(id){const obj=findObj();S.activeLayer=obj.layerId;if(!getLayer(obj.layerId)?.locked){drag={kind:'object',id,start:pt,points:clone(obj.points)};$('drawing').setPointerCapture(e.pointerId);}}renderUI();if(id)showRightPanel();return;}
 if(tool==='erase'){selected=hitObject(pt);deleteSelected();return;}if(tool==='calibrate'){draft.push(pt);if(draft.length===2){const pts=clone(draft);draft=[];calibrationDialog(pts);}requestRender();return;}if(!writable())return;
 if(tool==='text'){textDialog(pt);return;}if(tool==='pen'){draft=[pt];drag={kind:'pen'};$('drawing').setPointerCapture(e.pointerId);requestRender();return;}
 if(e.button!==2&&e.detail>=2)return;if(tool==='area'&&draft.length>=3&&RR.dist(draft[0],pt)<10/view.z){finishDraft();return;}if(tool==='vehicle'){addVehicleTarget(pt);return;}if(tool==='pilbil'){pilbilPlace(pt);return;}if(tool==='lark'){larkClick(pt);return;}if(!draft.length||RR.dist(draft.at(-1),pt)>1e-8)draft.push(pt);if(['line','rect'].includes(tool)&&draft.length===2){addObject(tool,draft);selected=null;}renderStatus();requestRender();
}
function handleMove(e){if(!page())return;const raw=worldPos(e);hover=raw;if(drag?.kind==='pan'){view.x=drag.view.x+e.clientX-drag.start.x;view.y=drag.view.y+e.clientY-drag.start.y;requestRender();return;}const pt=snapped(raw,e);hover=pt;if(drag&&['object','node'].includes(drag.kind)&&!drag.recorded){snapshot();drag.recorded=true;}if(drag?.kind==='pen'){if(RR.dist(draft.at(-1),pt)>1.5/view.z)draft.push(pt);}else if(drag?.kind==='object'){const o=findObj();if(o)o.points=drag.points.map(q=>({x:q.x+pt.x-drag.start.x,y:q.y+pt.y-drag.start.y}));sweepCache.delete(drag.id);changed();}else if(drag?.kind==='node'){const o=findObj();if(o)o.points[drag.index]=pt;sweepCache.delete(drag.id);changed();}const p=page();$('coords').textContent=scaled(p)?`x ${nf(pt.x*p.scale.x)} m · y ${nf(pt.y*p.scale.y)} m`:`x ${nf(pt.x,1)} · y ${nf(pt.y,1)}`;requestRender();}
function handleUp(e){if(drag?.kind==='pen'&&draft.length>1){addObject('pen',draft);selected=null;}else if(drag?.kind==='pen')draft=[];if(drag&&['node','object'].includes(drag.kind)){changed();renderUI();}drag=null;if($('drawing').hasPointerCapture(e.pointerId))$('drawing').releasePointerCapture(e.pointerId);requestRender();}
function finishDraft(){if(!draft.length)return;const pts=clone(draft);if(tool==='lark'){try{finishLark();}catch(e){toast(e.message);return;}}else if(tool==='measure'&&pts.length>=2)addObject('measure',pts);else if(tool==='area'&&pts.length>=3){if(!RR.simplePolygon(pts)){toast('Ytans kanter korsar varandra. Flytta punkterna eller rita om.');return;}if(RR.area(pts)<1e-10){toast('Ytan måste ha en utbredning.');return;}addObject('area',pts);}else if(tool==='street'&&pts.length>=2){try{if(!confirmed(page()))throw Error('Bekräfta skalan först.');const s=getSection(streetSectionId);if(!s?.name.trim()||!s.items.length)throw Error('Välj en namngiven sektion med minst ett element.');streetGeometry({sectionId:s.id,points:pts},page());const o=addObject('street',pts,{sectionId:s.id,flip:false,name:s.name});if(o)selectObject(o.id);}catch(e){toast(e.message);return;}}else if(tool==='vehicle'&&pts.length>=2){try{const options=clone(vehicleSettings);const directions=pts.slice(2).map(q=>q.direction===-1?-1:1),points=pts.map(({x,y})=>({x,y}));const sw=RR.simulateArcRoute(points,options.vehicle,page().scale,directions,options.margin);if(!sw.valid){toast(sw.issues[0]);return;}const o=addObject('vehicle',points,{vehicle:options.vehicle,radius:options.radius,margin:options.margin,name:options.vehicle.name,directions,pathModel:'rear-arcs',frame:100});if(o)sweepCache.set(o.id,{key:sweepKey(o,page()),data:sw});if(sw.issues.length)toast(sw.issues[0]);if(o)selectObject(o.id);renderInspector();}catch(e){toast(e.message);return;}}else{toast(tool==='area'?'Placera minst tre punkter.':'Placera minst två punkter.');return;}draft=[];renderStatus();requestRender();}
function textDialog(pt,o){if(o&&getLayer(o.layerId)?.locked)return;let formatting=textFormat(o);modal(o?'Redigera text':'Lägg till text',textFormatPanel('dialogFormat',formatting)+`<label class="field"><span>Text / kommentar</span><textarea id="newText" maxlength="10000">${esc(o?.text||'')}</textarea></label><p class="tiny">Formateringen gäller hela textobjektet. Skapa flera texter för olika formatering.</p><div class="modal-actions"><button id="cancelText">Avbryt</button><button id="commitText" class="primary">${o?'Spara':'Placera text'}</button></div>`);bindTextFormat('dialogFormat',formatting,f=>formatting=f,false,'newText');$('newText').focus();$('cancelText').onclick=closeModal;$('commitText').onclick=()=>{const text=$('newText').value.trim();if(!text)return;if(o){if(getLayer(o.layerId)?.locked)return;snapshot();Object.assign(o,{text},textFields(formatting));changed();renderUI();}else{const created=addObject('text',[pt],{text,...textFields(formatting)});if(!created)return;style.font=formatting.size;Object.assign(style,{fontFamily:formatting.family,fontBold:formatting.bold,fontItalic:formatting.italic,fontUnderline:formatting.underline});}closeModal();};}
function zoom(f,anchor={x:cw/2,y:ch/2}){const before={x:(anchor.x-view.x)/view.z,y:(anchor.y-view.y)/view.z};view.z=RR.clamp(view.z*f,1e-6,1e6);view.x=anchor.x-before.x*view.z;view.y=anchor.y-before.y*view.z;requestRender();}
function pageFitZoom(p,w=cw,h=ch){return Math.max(1e-6,Math.min((w-32)/p.w,(h-32)/p.h));}
function fitPage(){const p=page();if(!p)return;view.z=pageFitZoom(p);view.z=Math.max(view.z,1e-6);view.x=(cw-p.w*view.z)/2;view.y=(ch-p.h*view.z)/2;requestRender();}
async function activatePage(id){if(importing)return;draft=[];selected=null;drag=null;S.activePage=id;try{busy('Visar ritningen…');await ensureBackground(page());fitPage();renderUI();}catch(e){errorBox(e);}finally{unbusy();}}
function vehiclePanel(o){const v=o?.vehicle||vehicleSettings.vehicle,r=o?.radius??vehicleSettings.radius,m=o?.margin??vehicleSettings.margin,sw=o?getSweep(o,page()):null;return`${!o?`<p class="note">1. Placera <strong>bakaxelns centrum</strong>.<br>2. Klicka i <strong>nosens riktning</strong>.<br>3. Välj körriktning och klicka mål för bakaxeln. Svängen visas före klicket.</p><div class="row gear-controls"><button id="gearForward" class="${vehicleSettings.gear===1?'primary':''}" aria-pressed="${vehicleSettings.gear===1}">Framåt</button><button id="gearReverse" class="${vehicleSettings.gear===-1?'primary':''}" aria-pressed="${vehicleSettings.gear===-1}">Backa</button></div><p class="tiny">Högerklick växlar framåt/backa. Vänsterklick lägger till målet. Enter avslutar. Backsteg ångrar.</p>`:o.pathModel!=='rear-arcs'?'<p class="note warn">Äldre körspårsmodell. Rita en ny manöver för att använda den nya fordonsmodellen.</p><button id="redrawVehicle" class="full">Rita ny manöver med detta fordon</button>':'<p class="note">Noderna anger bakaxelns läge. Den första riktningspunkten anger nosriktningen. Dra en nod för att justera manövern.</p>'}<label class="field"><span>Fordon</span><select id="vehicleSelect">${VEHICLES.map(a=>`<option value="${a.id}" ${v.id===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><table class="vehicle-specs"><tr><td>Längd × bredd</td><td>${nf(v.length)} × ${nf(v.width)} m</td></tr><tr><td>Axelavstånd</td><td>${nf(v.wheelbase)} m</td></tr><tr><td>Överhäng fram / bak</td><td>${nf(v.frontOverhang)} / ${nf(v.rearOverhang)} m</td></tr></table><p class="tiny">${esc(v.source)}${v.id!=='custom'?' · äldre VGU-tabell':''}</p>${v.id==='custom'?`<details open><summary>Egna fordonsmått</summary>${field('Längd (m)','vLength',v.length)}${field('Bredd (m)','vWidth',v.width)}${field('Axelavstånd (m)','vWheelbase',v.wheelbase)}${field('Överhäng fram (m)','vFront',v.frontOverhang)}</details>`:''}<div class="row">${o&&o.pathModel!=='rear-arcs'?field('Svängradie (m)¹','vRadius',r):''}${field('Marginal (m)','vMargin',m)}</div>${field('Max styrvinkel (grader)²','vSteer',v.maxSteer)}<p class="tiny">${o&&o.pathModel!=='rear-arcs'?'¹ Framaxelns centrumlinje.<br>':''}² Modellantagande, ändringsbart. Inte ett VGU-krav.</p><p class="tiny">Blått = framåt · orange = backning. Bakaxelns mål markeras med en ring. Styrningen beräknas från fordonets läge till målet.</p>${sw?`<div class="note ${sw.issues.length?'error':''}" style="margin-top:12px">${sw.issues.length?esc(sw.issues.join(' ')):`Beräknat maxutslag: ${nf(sw.maxSteer,1)}°. Inom vald styrgräns.`}</div><label class="field"><span>Fordonets läge längs körvägen</span><input id="vehicleFrame" type="range" min="0" max="100" value="${o.frame??100}"></label><button class="full" id="playVehicle">Spela / pausa körningen</button>`:''}<div class="note warn" style="margin-top:15px">Översiktlig simulering av stela fordon, framåt och bakåt i låg fart. Karossens svep och vald marginal visas. Hinder och fria avstånd bedöms visuellt.</div><button class="full link-button" id="vehicleSources">Fordonsdata & beräkningsmodell</button>`;}
function bindVehicle(o){if($('gearForward'))$('gearForward').onclick=()=>setVehicleGear(1);if($('gearReverse'))$('gearReverse').onclick=()=>setVehicleGear(-1);if($('redrawVehicle'))$('redrawVehicle').onclick=()=>{vehicleSettings.vehicle=clone(o.vehicle);vehicleSettings.margin=o.margin;setTool('vehicle');};const apply=fn=>{if(o&&getLayer(o.layerId)?.locked)return;try{if(o)snapshot();fn(o||vehicleSettings);if(o){sweepCache.delete(o.id);changed();}renderInspector();requestRender();}catch(e){toast(e.message);}};$('vehicleSelect').onchange=()=>apply(a=>{a.vehicle=clone(VEHICLES.find(v=>v.id===$('vehicleSelect').value));if(!o)vehicleSettings.radius=a.vehicle.wheelbase/Math.sin(a.vehicle.maxSteer*Math.PI/180)*1.2;});for(const [id,key,min,max]of[['vRadius','radius',.1,1000],['vMargin','margin',0,10]])if($(id))$(id).onchange=()=>apply(a=>{const n=number($(id).value);if(!Number.isFinite(n)||n<min||n>max)throw Error(`Ange ett värde mellan ${min} och ${max}.`);a[key]=n;});$('vSteer').onchange=()=>apply(a=>{const n=number($('vSteer').value);if(!Number.isFinite(n)||n<5||n>65)throw Error('Styrvinkeln ska ligga mellan 5 och 65 grader.');a.vehicle.maxSteer=n;});if($('vLength'))for(const id of ['vLength','vWidth','vWheelbase','vFront'])$(id).onchange=()=>apply(a=>{const v=a.vehicle,L=number($('vLength').value),w=number($('vWidth').value),ax=number($('vWheelbase').value),f=number($('vFront').value);if(![L,w,ax,f].every(Number.isFinite)||L<=0||L>40||w<=0||w>6||ax<=0||f<0||L<ax+f)throw Error('Kontrollera fordonsmåtten. Längden ska rymma axelavstånd och överhäng.');Object.assign(v,{length:L,width:w,wheelbase:ax,frontOverhang:f,rearOverhang:L-ax-f});});if($('vehicleFrame'))$('vehicleFrame').oninput=()=>{o.frame=number($('vehicleFrame').value);requestRender();};if($('playVehicle'))$('playVehicle').onclick=()=>{if(animation){cancelAnimationFrame(animation);animation=null;return;}if((o.frame??100)>=100)o.frame=0;let last=performance.now();const step=t=>{if(!findObj()||selected!==o.id){animation=null;return;}o.frame=Math.min(100,(o.frame||0)+(t-last)/150);last=t;if($('vehicleFrame'))$('vehicleFrame').value=o.frame;requestRender();if(o.frame>=100){animation=null;return;}animation=requestAnimationFrame(step);};animation=requestAnimationFrame(step);};$('vehicleSources').onclick=()=>openHelp('vehicle');}
function sweepKey(o,p){return JSON.stringify([o.points,o.vehicle,o.radius,o.margin,o.drive,o.directions,o.pathModel,p.scale?.x,p.scale?.y]);}function getSweep(o,p){if(!scaled(p))return null;const k=sweepKey(o,p),c=sweepCache.get(o.id);if(c?.key===k)return c.data;try{const data=calculateSweep(o,p);sweepCache.set(o.id,{key:k,data});return data;}catch(e){return null;}}

function calculateSweep(o,p){const sw=rigidSweep(o,p);return sw?RR.attachUnits(sw,o.vehicle,p.scale,o.margin):sw;}
function rigidSweep(o,p){if(o.drive?.control==='pilbil')return RR.simulatePilbil(o.points,o.vehicle,p.scale,o.drive.commands,o.margin);if(o.pathModel==='rear-arcs')return RR.simulateArcRoute(o.points,o.vehicle,p.scale,o.directions,o.margin);if(o.directions)return RR.simulateDirected(o.points,o.vehicle,p.scale,o.radius,o.margin,o.directions);const approach=o.drive?.placement?null:RR.simulate(o.points,o.vehicle,p.scale,o.radius,o.margin);return o.drive?RR.simulateManeuver(o.points,o.vehicle,p.scale,o.drive.commands,o.margin,approach):approach;}

const panelState={left:false,right:typeof innerWidth!=='undefined'&&innerWidth<=930},panelManual={left:false,right:false};
function renderPanels(){for(const side of ['left','right']){const collapsed=panelState[side],name=side==='left'?'underlag':'verktyg',button=$(side==='left'?'toggleLeftPanel':'toggleRightPanel');$('workspace').classList.toggle(side+'-collapsed',collapsed);button.setAttribute('aria-expanded',String(!collapsed));button.textContent=(collapsed?'Visa ':'Dölj ')+name;button.title=(collapsed?'Visa ':'Minimera ')+name;}if(!panelState.right)$('rightPanel').classList.add('show');requestRender();}
function togglePanel(side){panelState[side]=!panelState[side];panelManual[side]=panelState[side];renderPanels();}
function showRightPanel(){if(panelManual.right)return;panelState.right=false;renderPanels();}

function setVehicleGear(direction){vehicleSettings.gear=direction;renderInspector();renderStatus();requestRender();}
function vehicleDraftObject(points=draft){return{id:'vehicle-preview',kind:'vehicle',layerId:S.activeLayer,name:vehicleSettings.vehicle.name,points:points.map(({x,y})=>({x,y})),directions:points.slice(2).map(p=>p.direction||1),pathModel:'rear-arcs',vehicle:vehicleSettings.vehicle,radius:vehicleSettings.radius,margin:vehicleSettings.margin,frame:100};}
function addVehicleTarget(pt){try{
 if(!confirmed(page())){toast('Bekräfta skalan innan du kör.');return;}
 if(!draft.length){draft.push({...pt});}else if(draft.length===1){if(RR.length([draft[0],pt],page().scale)<.01){toast('Klicka längre från startpunkten för att ange nosriktningen.');return;}draft.push({...pt});}else{
  const points=[...draft,{...pt,direction:vehicleSettings.gear}],sw=calculateSweep(vehicleDraftObject(points),page());
  if(!sw.valid){toast(sw.issues[0]);return;}draft.push(points.at(-1));
 }
 selected=null;hover=null;renderInspector();renderStatus();requestRender();
}catch(e){toast(e.message);}
}

const TEXT_FONTS=[{id:'segoe',name:'Segoe UI',css:'"Segoe UI",Arial,sans-serif'},{id:'arial',name:'Arial',css:'Arial,Helvetica,sans-serif'},{id:'georgia',name:'Georgia',css:'Georgia,"Times New Roman",serif'},{id:'times',name:'Times New Roman',css:'"Times New Roman",Times,serif'},{id:'mono',name:'Courier New',css:'"Courier New",Courier,monospace'}];
function textFormat(o,p=page()){return{size:o?(o.fontSize||18*unit(p))/unit(p):style.font,family:o?(o.fontFamily||'segoe'):(style.fontFamily||'segoe'),bold:o?!!o.fontBold:!!style.fontBold,italic:o?!!o.fontItalic:!!style.fontItalic,underline:o?!!o.fontUnderline:!!style.fontUnderline};}
function textFields(f,p=page()){return{fontSize:f.size*unit(p),fontFamily:f.family,fontBold:f.bold,fontItalic:f.italic,fontUnderline:f.underline};}
function fontFamilyCSS(id){return(TEXT_FONTS.find(f=>f.id===id)||TEXT_FONTS[0]).css;}
function canvasTextFont(o,p=page()){return`${o.fontItalic?'italic':'normal'} ${o.fontBold?'700':'400'} ${(o.fontSize||18*unit(p))*pageAppearance(p).text}px ${fontFamilyCSS(o.fontFamily)}`;}
function textFormatPanel(prefix,f){return `<div class="text-format"><div class="row">${field('Textstorlek',prefix+'Size',Math.round(f.size*100)/100,'number','min="6" max="200" step="1"')}<label class="field"><span>Teckensnitt</span><select id="${prefix}Family">${TEXT_FONTS.map(font=>`<option value="${font.id}" ${font.id===f.family?'selected':''}>${font.name}</option>`).join('')}</select></label></div><div class="text-style-buttons" role="group" aria-label="Textstil">${[['bold','Fet','F'],['italic','Kursiv','K'],['underline','Understruken','U']].map(([key,label,letter])=>`<button type="button" id="${prefix}${key}" class="text-${key} ${f[key]?'active':''}" title="${label}" aria-label="${label}" aria-pressed="${f[key]}">${letter}</button>`).join('')}</div></div>`;}
function previewTextFormat(id,f){const el=$(id);if(!el)return;el.style.fontFamily=fontFamilyCSS(f.family);el.style.fontSize=f.size+'px';el.style.fontWeight=f.bold?'700':'400';el.style.fontStyle=f.italic?'italic':'normal';el.style.textDecoration=f.underline?'underline':'none';}
function bindTextFormat(prefix,format,commit,locked=false,previewId=null){let current={...format};const apply=next=>{if(locked)return;current=next;commit({...current});if(previewId)previewTextFormat(previewId,current);};
 const size=$(prefix+'Size'),family=$(prefix+'Family');size.disabled=family.disabled=locked;
 size.onchange=()=>{const n=number(size.value);if(!Number.isFinite(n)||n<6||n>200){toast('Välj textstorlek mellan 6 och 200.');size.value=current.size;return;}apply({...current,size:n});};
 family.onchange=()=>apply({...current,family:family.value});
 for(const key of ['bold','italic','underline']){const button=$(prefix+key);button.disabled=locked;button.onclick=()=>{if(locked)return;const next={...current,[key]:!current[key]};button.classList.toggle('active',next[key]);button.setAttribute('aria-pressed',String(next[key]));apply(next);};}
 if(previewId)previewTextFormat(previewId,current);
}

const canvas=$('drawing'),ctx=canvas.getContext('2d');
function requestRender(){if(!raf)raf=requestAnimationFrame(()=>{raf=0;draw();});}
function path(c,ps,close=false){if(!ps?.length)return;c.moveTo(ps[0].x,ps[0].y);for(let i=1;i<ps.length;i++)c.lineTo(ps[i].x,ps[i].y);if(close)c.closePath();}
