  let size=RR.PAPER[opt.paper];if(opt.paper==='source'){if(!['pdf','blank'].includes(p.kind))throw Error('Originalformat kräver PDF eller ett blankt papper. Välj annars ett pappersformat.');size=[p.w*25.4/72,p.h*25.4/72];}else size=r.w>=r.h?size:[size[1],size[0]];
