function getSection(id){return(S.sections||[]).find(s=>s.id===id);}
function sectionItem(type){const t=RS.type(type);return{id:uid(),type,label:t.label,width:t.width,gapAfter:null};}
function newSection(name,types=[]){const items=types.map(sectionItem);items.forEach((e,i)=>{if(i<items.length-1)e.gapAfter=.1;});return{id:uid(),name,items,availableWidth:null};}
function ensureSections(){S.sections??=[];if(!S.sections.length){snapshot();S.sections.push(newSection('Alternativ A',['walk','localbig','walk']),newSection('Alternativ B',['walk','cycle','localbig','walk']));S.sectionSlots=S.sections.map(s=>s.id);changed();}if(!Array.isArray(S.sectionSlots))S.sectionSlots=[S.sections[0].id,S.sections[1]?.id||null];for(let i=0;i<2;i++)if(!getSection(S.sectionSlots[i]))S.sectionSlots[i]=S.sections.find(s=>s.id!==S.sectionSlots[1-i])?.id||null;}
function switchWorkspace(mode){draft=[];hover=null;drag=null;workspaceMode=mode;const plan=mode!=='sections';$('workspace').hidden=!plan;$('mapToolbar').hidden=!plan;$('appearanceBar').hidden=true;$('appearanceToggle').setAttribute('aria-expanded','false');$('appearanceToggle').hidden=!plan;$('sectionWorkspace').hidden=plan;$('workspace').classList.toggle('lark-mode',mode==='lark');$('larkPalette').hidden=mode!=='lark';for(const [id,key]of[['mapTab','map'],['sectionsTab','sections'],['larkTab','lark']])$(id).setAttribute('aria-selected',String(mode===key));if(mode==='sections'){ensureSections();renderSections();$('toolHint').textContent='Sektionsbredder anges i meter. Ändringar sparas med projektet.';}else{if(mode==='map'&&tool==='lark')setTool('select');resize();renderUI();if(mode==='lark'&&page()&&confirmed(page())&&!selected)setTool('lark');}if(typeof renderPilbil==='function')renderPilbil();}

