let appearanceGesture=null;
function renderAppearance(){const p=page(),a=pageAppearance(p);if(appearanceGesture?.pageId!==p?.id)appearanceGesture=null;for(const [key,id,out]of[['line','mapLineSize','mapLineValue'],['text','mapTextSize','mapTextValue']]){const n=Math.round(a[key]*100);$(id).disabled=!p;$(id).value=n;$(id).setAttribute('aria-valuetext',n+' procent');$(out).textContent=n+' %';}$('appearanceReset').disabled=!p;}
