function toggleFocusLayout(){const entering=!focusLayout;if(entering){focusLayout={state:{...panelState},manual:{...panelManual}};panelState.left=panelState.right=true;panelManual.left=panelManual.right=true;}else{Object.assign(panelState,focusLayout.state);Object.assign(panelManual,focusLayout.manual);focusLayout=null;}$('appShell').classList.toggle('focus-layout',entering);$('focusToggle').textContent=entering?'Avsluta fokus':'Fokusläge';$('focusToggle').setAttribute('aria-pressed',String(entering));setAppearanceOpen(false);renderPanels();requestAnimationFrame(resize);}
function initAppearance(){$('appearanceToggle').onclick=()=>setAppearanceOpen($('appearanceBar').hidden);$('appearanceClose').onclick=()=>{setAppearanceOpen(false);$('appearanceToggle').focus();};$('focusToggle').onclick=toggleFocusLayout;document.addEventListener('pointerdown',e=>{if(!$('appearanceBar').hidden&&!$('appearanceBar').contains(e.target)&&!$('appearanceToggle').contains(e.target))setAppearanceOpen(false);});$('appearanceBar').addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();setAppearanceOpen(false);$('appearanceToggle').focus();}});for(const [key,id]of[['line','mapLineSize'],['text','mapTextSize']]){const el=$(id);el.onpointerdown=()=>{appearanceGesture=null;};el.oninput=()=>{const p=page(),n=Number(el.value)/100;if(!p||!Number.isFinite(n)||n<.01||n>3)return;if(!appearanceGesture||appearanceGesture.pageId!==p.id||appearanceGesture.key!==key){snapshot();appearanceGesture={pageId:p.id,key};}p.appearance={...pageAppearance(p),[key]:n};changed();renderAppearance();requestRender();};el.onchange=()=>{appearanceGesture=null;renderStatus();};el.onblur=()=>{appearanceGesture=null;};el.onpointerup=()=>{$('viewport').focus();};}$('appearanceReset').onclick=()=>{const p=page();if(!p)return;const a=pageAppearance(p);if(a.line!==1||a.text!==1){snapshot();p.appearance={line:1,text:1};changed();renderAppearance();renderStatus();requestRender();}$('viewport').focus();};}

