function createBlankProject(){pilbilId=null;if(animation){cancelAnimationFrame(animation);animation=null;}const first=layer('Granskning',palette[0]);S={format:'ritningsrummet',version:8,sections:[],sectionSlots:[null,null],name:'Ny granskning',documents:[],pages:[],layers:[first],activePage:null,activeLayer:first.id};renderCache.clear();pdfCache.clear();sweepCache.clear();history=[];future=[];draft=[];hover=null;snapPoint=null;selected=null;drag=null;space=false;selectedLayerEditor=false;streetSectionId=null;illustratedSectionId=null;calibrationMode='uniform';view={x:0,y:0,z:1};tool='select';dirty=false;$('projectName').value=S.name;$('saveState').textContent='Nytt projekt · lokalt på din dator';$('projectInput').value='';$('fileInput').value='';closeModal();enterWorkspace(true);setTool('select');}
function startNewProject(){if(!dirty){createBlankProject();return;}modal('Skapa ett nytt projekt',`<p>Det pågående projektet har ändringar som inte sparats.</p><div class="modal-actions"><button id="keepCurrentProject">Avbryt</button><button id="discardForNew">Börja utan att spara</button><button id="saveForNew" class="primary">Spara och skapa nytt</button></div>`);$('keepCurrentProject').onclick=closeModal;$('discardForNew').onclick=createBlankProject;$('saveForNew').onclick=()=>{saveProject();createBlankProject();};}
function initWelcome(){$('welcomeLoad').onclick=()=>{$('projectInput').value='';$('projectInput').click();};$('welcomeNew').onclick=startNewProject;$('welcomeResume').onclick=()=>enterWorkspace();$('homeBtn').onclick=showWelcome;}

function openHelp(section){modal(section==='vehicle'?'Fordonsdata & beräkningsmodell':'Så använder du Ritningsrummet',`${section!=='vehicle'?`<div class="help-step"><span>1</span><div><strong>Öppna en ritning</strong><p>PDF, JPG, PNG, WebP, ASCII DXF och förenklad SVG. Du kan släppa flera filer på ritningsytan. Varje PDF-sida får en egen skala och egna objekt.</p></div></div><div class="help-step"><span>2</span><div><strong>Kontrollera skalan</strong><p>PDF-text, lokal OCR och DXF-enheter kan ge ett förslag. Kalibrera helst mot ett långt känt avstånd och kontrollmät ett andra. En skalangivelse kan vara fel efter kopiering eller förminskning.</p></div></div><div class="help-step"><span>3</span><div><strong>Granska i egna lager</strong><p>Skapa och döp lager. Använd ögat för synlighet, låset för skrivskydd och ⋯ för namn, färg, genomskinlighet och ordning. Linjer, frihand, text, rektanglar, mått och körspår sparas i det aktiva lagret.</p></div></div><div class="help-step"><span>4</span><div><strong>Mät och redigera</strong><p>Text kan ges storlek, teckensnitt och fet, kursiv eller understruken stil, även i kombination. Välj formatering före placering eller markera en befintlig text. Dubbelklick öppnar textdialogen. Formateringen gäller hela textobjektet och följer med i projekt och export. Klicka punkt för punkt för längd och area. För körspår placerar du först fordonet och anger dess riktning. <kbd>Enter</kbd> eller dubbelklick avslutar. <kbd>Esc</kbd> avbryter. Markera och dra objekt eller noder. <kbd>Delete</kbd> raderar, <kbd>Ctrl Z</kbd> ångrar och <kbd>Ctrl Y</kbd> gör om. <kbd>Shift</kbd> låser nya segment till 45°. <kbd>Alt</kbd> stänger tillfälligt av snäppning.</p></div></div><div class="help-step"><span>5</span><div><strong>Spara eller exportera</strong><p>Spara projektet som JSON för att fortsätta senare. Originalunderlag bäddas in. PDF/JPG är sammanfogade granskningsbilder. Välj hela sidan eller utsnittet; PDF kan innehålla alla sidor och skrivas ut i bestämd skala.</p></div></div><p class="note">Rulla för att zooma. Håll mellanslag eller mushjulet nedtryckt och dra för att flytta vyn. <kbd>F</kbd> visar hela sidan. <kbd>Ctrl S</kbd> hämtar projektfilen. Spara regelbundet; arbetet sparas inte automatiskt.</p>`:''}
 <details><summary>Pilbil: kör med piltangenter</summary><p>Välj Pilbil. Klicka för bakaxelns centrum och klicka sedan i nosens riktning. Uppåt kör framåt, nedåt backar. Varje tryck kör vald sträcka, 0,1–1 meter (förval 0,5 m). Hållna tangenter upprepas inte. Vänster och höger ändrar framhjulens styrvinkel med valt styrsteg, inom fordonets styrgräns. Utslaget ligger kvar när riktningen byts. 0 rätar upp hjulen.</p><p>Den flyttbara rutan visar en schematisk ratt och den verkliga modellvinkeln för framhjulen. Dra i rubriken för att flytta rutan. Ångra körsteg tar bort senaste rörelsen. Ctrl+Z ångrar senaste ändringen. Enter eller stängknappen avslutar körläget. Alla steg sparas direkt i det aktiva lagret och följer med vid projektsparning och export. Markera bilen och välj Kör vidare med Pilbil för att fortsätta.</p><p>Det är en geometrisk simulering utan hastighet. Varje körsteg har konstant styrvinkel; rattändringar sker stillastående. Samma stela fordonsmått och styrgränser används som för övriga körspår.</p></details><details><summary>Blankt papper och LARK</summary><p>Välj Blankt papper på framsidan eller under Underlag. Ange format, orientering och skala. Pappret kan användas med alla ritverktyg. Under Skala ändrar du pappersformat och skala; objektens verkliga mått bevaras.</p><p>Fliken LARK använder samma ritningsyta och lager som Plankarta. Välj växtlighet, markmaterial, vatten eller utrustning. Klicka för att sätta ut symboler. Markmaterial ritas som en kontur med minst tre hörn och avslutas med Enter. Välj-verktyget låter dig flytta objekt och hörnpunkter. Bredd, djup, rotation, beteckning och fyllning redigeras i högerpanelen. Elementen sparas i JSON och följer med i PDF och JPG.</p><p>Biblioteket innehåller generella plansymboler och redigerbara skissmått. Det återger inte en bestämd standard eller leverantörskatalog. Trädens mått avser kronans utbredning i plan. Materialmönster är schematiska.</p></details><details><summary>Gatusektioner: jämförelse, illustration och plankarta</summary><p>Öppna Gatusektioner för två alternativ i samma visningsskala. Lägg till element, ändra bredder och skyddsavstånd, byt ordning med pilar eller drag och döp varje sektion. Kopiera till det andra fönstret för ett oberoende alternativ. Täby TH25 används där ett grundmått finns; övriga element har märkta skissvärden. Skyddsavståndet 0,10 m är ditt förval.</p><p>Illustrera öppnar en separat måttsatt skiss som kan hämtas som JPG eller PDF. Välj Rita i plankartan och klicka längs hela sektionens mittlinje, efter att ritningens skala bekräftats. Enter avslutar. Sektionens vänstra sida följer riktningen från första till sista noden. Byt sida i objektpanelen vid behov. För skarpa hörn eller överlappande band måste linjen justeras. Ändringar i sektionen uppdaterar dess placeringar även på dolda eller låsta lager. Kopiera sektionen för en oberoende variant. Alla sektioner och placeringar följer med i JSON-projektet.</p></details>
 <details ${section==='vehicle'?'open':''}><summary>Körspår: fordonsdata och antaganden</summary><p>Inbyggda karossmått kommer från Trafikverkets VGU, <em>Begrepp och grundvärden</em>, figurerna 2.2-6 och 2.2-10. Det är äldre typfordonstabeller. Programmet är inte en kontroll av att en utformning uppfyller aktuell VGU.</p><table class="source-table"><thead><tr><th>Fordon</th><th>Längd</th><th>Bredd</th><th>Axelavst.</th><th>Fram / bak</th></tr></thead><tbody>${VEHICLES.filter(v=>v.id!=='custom').map(v=>`<tr><td>${v.id}</td><td>${nf(v.length)} m</td><td>${nf(v.width)} m</td><td>${nf(v.wheelbase)} m</td><td>${nf(v.frontOverhang)} / ${nf(v.rearOverhang)} m</td></tr>`).join('')}</tbody></table><p>Bakre överhäng är beräknat som längd minus axelavstånd och främre överhäng. Gränsen 35° är ett ändringsbart modellantagande; den är inte hämtad som ett VGU-krav. Välj eget stelt fordon för andra indata.</p><p>Den nya modellen bygger upp manövern från fordonets aktuella position. Första klicket placerar bakaxelns centrum. Andra klicket anger nosens riktning. Därefter anger du mål för bakaxeln med vänsterklick. Flytta musen för att förhandsvisa sväng och kaross innan du klickar.</p><p>Välj Framåt eller Backa i panelen. Högerklick växlar körriktning utan att lägga till en punkt. Vald riktning gäller tills du byter igen. Bakaxeln markeras med en ring och nosen med FRONT. Enter eller dubbelklick avslutar, Backsteg tar bort den senaste punkten. Du kan minimera panelerna och fortfarande byta riktning med högerklick.</p><p>Varje mål nås med en raksträcka eller en cirkelbåge som ansluter till bilens aktuella riktning. Styrvinkeln räknas ut från målet och får inte överskrida vald styrgräns. Rörelsen beräknas exakt med en kinematisk cykelmodell utan sidoslip, med högst 0,10 m och 0,5° per visat steg. Framåt och backning använder samma beräkning med positiv respektive negativ körsträcka. Position och nosriktning bevaras när växeln byts.</p><p>En delsträcka har konstant styrning. Vid nästa mål kan du ändra styrningen eller byta körriktning; ändringen antas ske stillastående. Lägg flera mål för en sammansatt sväng eller parkeringsmanöver. Programmet söker inte automatiskt efter en komplett parkeringsväg. En röd förhandsvisning betyder att målet inte kan nås med den enskilda delsträckan från aktuellt läge, inte att hela parkeringsmanövern är omöjlig. Flytta målet eller lägg in en korrigering. Omöjliga mål läggs inte till.</p><p>Bakaxelns körväg är blå vid framåt och orange vid backning. Framaxelns spår är gråstreckat. Karossens svepyta, hörnspår och vald marginal visas. Äldre sparade körspår behåller sin ursprungliga modell; använd ”Rita ny manöver med detta fordon” för den nya beräkningen.</p><p>Omfattning: stela fordon framåt och bakåt i låg fart. Ledbuss, släp, styrd boggi, styrhastighet, speglar, lutning och dynamiska effekter ingår inte. En simulering inom vald styrgräns är inte ett intyg om framkomlighet eller säkerhetsavstånd. Inga automatiska hinderkontroller görs.</p><p><a href="https://trafikverket.diva-portal.org/smash/get/diva2%3A1542418/FULLTEXT01.pdf" target="_blank" rel="noopener">Fordonsgeometrins källtabeller, Trafikverket</a><br><a href="https://bransch.trafikverket.se/for-dig-i-branschen/vag/Utformning-av-vagar-och-gator/vagar-och-gators-utformning-vgu/" target="_blank" rel="noopener">Aktuellt VGU: TRVINFRA-00396 och TRV 2024:148</a>. Källänkar kräver internet; verktyget i övrigt fungerar offline.</p></details>
 <details><summary>Skala, noggrannhet och flera skalor på samma ritning</summary><p>Alla mått avser planprojektionen. Ingen höjd, lutningslängd, geodesi eller SWEREF-transformering beräknas. Modellskalan sparas som meter per ritningsenhet i X/Y. Bildskärmen och zoomnivån påverkar inte måttet.</p><p>För PDF används sidans fysiska storlek i PDF-punkter, inklusive rotation och UserUnit. Skaltext efter förminskning måste korrigeras via originalformat eller referensmått. För en bild krävs dessutom tillförlitlig DPI eller originalformat. DPI i metadata kan vara en standardinställning och behöver kontrolleras.</p><p>OCR söker normalt i nedre högra delen av arket. Prova hela sidan om namnrutan finns någon annanstans. Små, roterade eller otydliga tecken kan missas. OCR-resultatet är alltid ett förslag.</p><p>Referenskalibrering ersätter den tidigare skalan och räknar om befintliga mått och körspår. Separat X/Y-kalibrering kan hantera likformig töjning i skanningen. Ett fotograferat ark i perspektiv behöver först rätas upp utanför programmet.</p><p>Varje sida har en skala. Importera samma sida ytterligare en gång för mätningar i en detaljvy med annan skala. Programmet upptäcker inte gränser mellan olika skalområden automatiskt. Kontrollgränsen 2 % är en tydligt vald granskningsgräns i detta verktyg.</p></details>
 <details><summary>CAD-stöd och filgränser</summary><p>DXF läses från modellrymden. Stöd finns för LINE, LWPOLYLINE med bulgebågar, 2D POLYLINE, CIRCLE, ARC, ELLIPSE, POINT, SOLID, TRACE, 3DFACE i XY-projektion, TEXT/MTEXT och nästlade INSERT-block. DIMENSION visas via sitt grafikblock när det finns. Externa referenser måste bindas in före export.</p><p>SPLINE, HATCH, proxyobjekt, 3D-polyline, alternativa OCS-plan och pappersrymd stöds inte. De räknas och redovisas som importanmärkningar. Måttsättningsstilar och CAD-typsnitt återges förenklat. Använd PDF när den exakta grafiska återgivningen behövs.</p><p>DWG, DGN, DWF och binär DXF behöver exporteras till ASCII DXF eller PDF i CAD-programmet. SVG återges förenklat; aktiva element, extern grafik och stilmallar rensas. Originalfiler upp till 120 MB, bilder upp till 80 miljoner bildpunkter och PDF upp till 150 sidor tillåts. Praktiska gränser beror på datorns minne.</p></details>
 <details><summary>Lokala filer, webbläsare och komponenter</summary><p>Öppna den nedladdade HTML-filen i en modern Edge eller Chrome på dator. All filbehandling, OCR, beräkning och export sker lokalt. Ingen ritning laddas upp.${ASSET_MAP?' Inga komponenter hämtas från internet.':' Komponenterna hämtas från samma server som sidan.'} JSON-filen innehåller de inlästa ritningarna.</p><p>Inbyggda komponenter: Mozilla PDF.js 5.6.205 (Apache 2.0), pdf-lib 1.17.1 (MIT) och Tesseract.js-core 7.0.0 med engelsk språkmodell för numerisk skaltext (Apache 2.0). ${ASSET_MAP?'Programmet och läsbara källfiler ligger inuti HTML-filen.':'Programmet och dess källfiler ligger bredvid sidan på servern.'}</p><button id="licensesBtn" class="full">Visa komponenternas licenser</button></details><div class="modal-actions"><button id="helpClose">Stäng</button></div>`);$('helpClose').onclick=closeModal;$('licensesBtn').onclick=async()=>{modal('Komponentlicenser',`<pre style="white-space:pre-wrap;font-size:12px">${esc(await assetText('licenses'))}</pre><button id="licClose" class="full">Stäng</button>`);$('licClose').onclick=closeModal;};}
function demoDXF(){const lines=[],g=(c,v)=>{lines.push(String(c),String(v));},poly=(pts,closed=true)=>{g(0,'LWPOLYLINE');g(8,'Kantsten');g(90,pts.length);g(70,closed?1:0);for(const[x,y]of pts){g(10,x);g(20,y);}},text=(x,y,t,h=1.2)=>{g(0,'TEXT');g(8,'Text');g(10,x);g(20,y);g(40,h);g(1,t);};g(0,'SECTION');g(2,'HEADER');g(9,'$INSUNITS');g(70,6);g(0,'ENDSEC');g(0,'SECTION');g(2,'ENTITIES');poly([[0,0],[100,0],[100,66],[0,66]]);poly([[8,24],[63,24],[63,57]],false);poly([[8,32],[55,32],[55,57]],false);poly([[14,33],[44,33],[44,38],[14,38]]);for(let x=16.5;x<44;x+=2.5)poly([[x,33],[x,38]],false);poly([[14,18],[44,18],[44,23],[14,23]]);for(let x=16.5;x<44;x+=2.5)poly([[x,18],[x,23]],false);poly([[65,10],[92,10],[92,39],[65,39]]);text(69,27,'BYGGNAD',2);text(69,24,'Exempelunderlag',1);text(12,42,'PARKERING / ANGÖRING',1.6);text(10,61,'EXEMPELRITNING – FIKTIV PLATS',1.5);text(9,7,'Referens 20,00 m',1);poly([[9,5],[29,5]],false);poly([[9,4.5],[9,5.5]],false);poly([[29,4.5],[29,5.5]],false);text(55,4,'Modell i meter · kontrollmått 20 m',1);g(0,'ENDSEC');g(0,'EOF');return lines.join('\n')+'\n';}
async function loadDemo(){try{importing=true;busy('Öppnar exempelritningen…');const file=new File([demoDXF()],'Exempel_Angoring.dxf',{type:'application/dxf'});await importFile(file);page().scale.status='confirmed';page().scale.source='Fiktiv exempelritning konstruerad i meter';renderUI();unbusy();toast('Exempel i meter. Prova längdmåttet 20 m nere till vänster.');}catch(e){errorBox(e);}finally{unbusy();importing=false;}}
