canvas.addEventListener('pointerdown',handleDown);canvas.addEventListener('pointermove',handleMove);canvas.addEventListener('pointerup',handleUp);canvas.addEventListener('pointercancel',e=>{drag=null;draft=[];requestRender();});canvas.addEventListener('dblclick',e=>{if(['measure','area','vehicle','street','lark'].includes(tool)){if(draft.length>1&&RR.dist(draft.at(-1),draft.at(-2))<2/view.z)draft.pop();finishDraft();}else if(tool==='select'){const id=hitObject(worldPos(e));selected=id;const o=findObj();if(o?.kind==='text'&&!getLayer(o.layerId)?.locked)textDialog(o.points[0],o);}});canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),{x:e.clientX-r.left,y:e.clientY-r.top});},{passive:false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
const viewport=$('viewport');viewport.addEventListener('dragover',e=>{e.preventDefault();viewport.classList.add('drop-active');});viewport.addEventListener('dragleave',()=>viewport.classList.remove('drop-active'));viewport.addEventListener('drop',e=>{e.preventDefault();viewport.classList.remove('drop-active');const files=[...e.dataTransfer.files];if(files.length===1&&/\.(json|rrproject)$/i.test(files[0].name))loadProject(files[0]);else importFiles(files);});
window.addEventListener('keydown',e=>{if(!$('welcomePage').hidden)return;if($('modal').open||$('sectionIllustration').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();e.target.blur?.();saveProject();return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(handlePilbilKey(e))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?restoreHistory(future,history):restoreHistory(history,future);return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();restoreHistory(future,history);return;}if(workspaceMode==='sections')return;if(e.code==='Space'){e.preventDefault();space=true;renderStatus();}if(e.key==='Escape'){draft=[];selected=null;drag=null;if(innerWidth<=930){panelState.right=true;renderPanels();}if(tool==='calibrate')setTool('select');renderUI();}if(e.key==='Enter')finishDraft();if(e.key==='Delete'||e.key==='Backspace'){if(draft.length){e.preventDefault();draft.pop();renderStatus();requestRender();}else deleteSelected();}if(e.key.toLowerCase()==='f')fitPage();const keys={v:'select',h:'hand',p:'pen',l:'line',t:'text',m:'measure',a:'area',k:'vehicle'};if(keys[e.key.toLowerCase()]&&!e.ctrlKey&&!e.metaKey)setTool(keys[e.key.toLowerCase()]);});window.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;renderStatus();}});window.addEventListener('blur',()=>{space=false;drag=null;});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});

